// Minimal gRPC-web (binary) unary client for the ChirpStack v4 API.
//
// ChirpStack v4 serves gRPC and gRPC-web on the same port as its web UI, so
// this works through reverse proxies (Caddy, nginx) and HTTP proxies that do
// not pass native gRPC/HTTP2 trailers.

import { EnvHttpProxyAgent, setGlobalDispatcher } from 'undici';

if (process.env.HTTPS_PROXY || process.env.https_proxy) {
  // Respect HTTPS_PROXY / NO_PROXY for outbound calls.
  setGlobalDispatcher(new EnvHttpProxyAgent());
}

/** Anything generated by protoc for google-protobuf. */
export interface PbMessage {
  serializeBinary(): Uint8Array;
}
export interface PbClass<T> {
  deserializeBinary(bytes: Uint8Array): T;
}

export class GrpcError extends Error {
  constructor(
    readonly method: string,
    readonly code: number,
    readonly details: string,
  ) {
    super(`ChirpStack ${method} failed (gRPC ${code}${GRPC_CODES[code] ? ' ' + GRPC_CODES[code] : ''}): ${details}`);
  }
}

export const GRPC_CODES: Record<number, string> = {
  1: 'CANCELLED', 2: 'UNKNOWN', 3: 'INVALID_ARGUMENT', 4: 'DEADLINE_EXCEEDED', 5: 'NOT_FOUND',
  6: 'ALREADY_EXISTS', 7: 'PERMISSION_DENIED', 8: 'RESOURCE_EXHAUSTED', 9: 'FAILED_PRECONDITION',
  10: 'ABORTED', 11: 'OUT_OF_RANGE', 12: 'UNIMPLEMENTED', 13: 'INTERNAL', 14: 'UNAVAILABLE',
  15: 'DATA_LOSS', 16: 'UNAUTHENTICATED',
};

/** Wrap a protobuf message in a gRPC length-prefixed data frame. */
export function encodeFrame(body: Uint8Array): Uint8Array<ArrayBuffer> {
  const frame = new Uint8Array(5 + body.length);
  new DataView(frame.buffer).setUint32(1, body.length);
  frame.set(body, 5);
  return frame;
}

/** Split a gRPC-web response body into its data message and trailers. */
export function decodeFrames(buf: Uint8Array): { data?: Uint8Array; trailers: Record<string, string> } {
  const trailers: Record<string, string> = {};
  let data: Uint8Array | undefined;
  let i = 0;
  while (i + 5 <= buf.length) {
    const flag = buf[i];
    const len = new DataView(buf.buffer, buf.byteOffset + i + 1, 4).getUint32(0);
    const chunk = buf.subarray(i + 5, i + 5 + len);
    i += 5 + len;
    if (flag & 0x80) {
      for (const line of new TextDecoder().decode(chunk).split(/\r?\n/)) {
        const idx = line.indexOf(':');
        if (idx > 0) trailers[line.slice(0, idx).trim().toLowerCase()] = line.slice(idx + 1).trim();
      }
    } else {
      data = chunk;
    }
  }
  return { data, trailers };
}

export class GrpcWebClient {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string,
    private readonly timeoutMs = 20_000,
  ) {}

  async unary<T>(method: string, req: PbMessage, resp: PbClass<T>): Promise<T> {
    const res = await fetch(`${this.baseUrl}/${method}`, {
      method: 'POST',
      headers: {
        'content-type': 'application/grpc-web+proto',
        'x-grpc-web': '1',
        accept: 'application/grpc-web+proto',
        authorization: `Bearer ${this.token}`,
      },
      body: encodeFrame(req.serializeBinary()),
      signal: AbortSignal.timeout(this.timeoutMs),
    });
    if (!res.ok) throw new GrpcError(method, 14, `HTTP ${res.status} ${res.statusText}`);
    const { data, trailers } = decodeFrames(new Uint8Array(await res.arrayBuffer()));
    // A trailers-only response puts the status in the HTTP headers instead.
    const status = Number(trailers['grpc-status'] ?? res.headers.get('grpc-status') ?? 0);
    if (status !== 0) {
      const msg = trailers['grpc-message'] ?? res.headers.get('grpc-message') ?? '';
      throw new GrpcError(method, status, safeDecode(msg));
    }
    return resp.deserializeBinary(data ?? new Uint8Array());
  }
}

/** Server-streaming call: yields each decoded message until the stream ends or the signal aborts. */
export async function* streamCall<T>(
  baseUrl: string,
  token: string,
  method: string,
  req: PbMessage,
  resp: PbClass<T>,
  signal?: AbortSignal,
): AsyncGenerator<T> {
  const res = await fetch(`${baseUrl}/${method}`, {
    method: 'POST',
    headers: {
      'content-type': 'application/grpc-web+proto',
      'x-grpc-web': '1',
      authorization: `Bearer ${token}`,
    },
    body: encodeFrame(req.serializeBinary()),
    signal,
  });
  if (!res.ok || !res.body) throw new GrpcError(method, 14, `HTTP ${res.status} ${res.statusText}`);
  const status = res.headers.get('grpc-status');
  if (status && status !== '0') throw new GrpcError(method, Number(status), safeDecode(res.headers.get('grpc-message') ?? ''));
  let buf = new Uint8Array();
  try {
    for await (const chunk of res.body as unknown as AsyncIterable<Uint8Array>) {
      const n = new Uint8Array(buf.length + chunk.length);
      n.set(buf);
      n.set(chunk, buf.length);
      buf = n;
      while (buf.length >= 5) {
        const len = new DataView(buf.buffer, buf.byteOffset + 1, 4).getUint32(0);
        if (buf.length < 5 + len) break;
        const flag = buf[0];
        const data = buf.slice(5, 5 + len);
        buf = buf.slice(5 + len);
        if (flag & 0x80) return;
        yield resp.deserializeBinary(data);
      }
    }
  } catch (e) {
    if ((e as Error).name === 'TimeoutError' || (e as Error).name === 'AbortError') return;
    throw e;
  }
}

function safeDecode(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}
